import{_ as r,o as e,c as i,a2 as l}from"./chunks/framework.CRFziyHp.js";const o="/images/placeholder-meilisearch-admin.svg",t="/images/placeholder-search-recommend-arch.svg",f=JSON.parse('{"title":"搜索与推荐","description":"","frontmatter":{},"headers":[],"relativePath":"features/search.md","filePath":"features/search.md","lastUpdated":1785013113000}'),s={name:"features/search.md"};function n(h,a,c,d,p,u){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="搜索与推荐" tabindex="-1">搜索与推荐 <a class="header-anchor" href="#搜索与推荐" aria-label="Permalink to &quot;搜索与推荐&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>维护全站内容搜索索引，查看 Meilisearch 同步状态；相关推荐依赖可选推荐服务（如 Gorse）。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>搜索能力已在授权或部署中启用。</li><li><strong>可选</strong>：若使用独立 Meilisearch 容器，需先完成 <a href="/ops/docker-infra">可选基础设施</a> 部署，并由运维将密钥写入服务器配置。</li><li>账号具备 <strong>系统监控</strong> 相关读权限。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="搜索索引" tabindex="-1">搜索索引 <a class="header-anchor" href="#搜索索引" aria-label="Permalink to &quot;搜索索引&quot;">​</a></h3><p>路径：<strong>系统监控 → 搜索索引</strong></p><p>页面通常展示：</p><ul><li>Meilisearch 连接状态（在线 / 离线）</li><li>各索引文档数量、最后同步时间</li><li><strong>手动重建 / 全量同步</strong> 按钮（慎用，高峰期可能增加负载）</li></ul><p>管理员职责：</p><ol><li>上线新区域或大批量导入内容后，查看索引数量是否增长</li><li>若客户端搜索明显缺失新内容，在运维确认 Meilisearch 正常后，使用页面提供的 <strong>重建索引</strong>（若有）</li><li>持续失败时记录页面错误信息并联系运维</li></ol><p><img src="'+o+'" alt="搜索索引示意"></p><h3 id="相关推荐-可选" tabindex="-1">相关推荐（可选） <a class="header-anchor" href="#相关推荐-可选" aria-label="Permalink to &quot;相关推荐（可选）&quot;">​</a></h3><p>路径：<strong>系统监控 → 相关推荐评估</strong></p><p>若部署了 Gorse 等推荐引擎，可在此查看推荐效果指标。未部署时菜单可能为空或提示未连接。</p><p>推荐服务为 <strong>可选组件</strong>，不影响基础搜索；启动方式见 <a href="/ops/docker-infra">可选基础设施</a>。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>搜索索引一般为 <strong>全站统一</strong>，文档内带有 region_id 字段供客户端过滤；<strong>不需要</strong>在区域管理单独开开关。</p><p>区域只影响「用户能看到哪些内容」，索引本身仍包含全站文档。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>发布一条带独特关键词的测试笔记，等待数分钟（或触发同步后）。</li><li>客户端搜索该关键词，能命中刚发布的笔记。</li><li><strong>系统监控 → 搜索索引</strong> 中文档总数与最近同步时间合理更新。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>搜索无结果但内容存在</strong></p><ul><li><strong>搜索索引</strong> 页 Meilisearch 是否离线；联系运维启动 Docker 栈或检查密钥。</li><li>笔记是否未审核通过或被区域距离过滤（客户端层）。</li></ul><p><strong>重建索引很慢</strong></p><ul><li>大数据量正常；建议在低峰操作，并由运维监控服务器 CPU / 内存。</li></ul><p><strong>没有搜索索引菜单</strong></p><ul><li>当前账号无监控权限；或搜索模块未启用。</li></ul><p><strong>Meilisearch 是否必须</strong></p><ul><li>小规模可依赖内置能力；生产环境建议独立 Meilisearch 以保障性能，详见 <a href="/ops/docker-infra">可选基础设施</a>。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/ops/docker-infra">可选基础设施</a></li><li><a href="/ops/monitoring">系统监控入口</a></li><li><a href="/features/circle-note">圈子与笔记</a></li></ul><p><img src="'+t+'" alt="搜索推荐架构示意"></p>',34)])])}const m=r(s,[["render",n]]);export{f as __pageData,m as default};
